import math

# --- Constants and Setup ---
BOARD_SIZE = 38.0

# Directions mapping: (dx, dy)
# 0: +X (Right), 1: -X (Left), 2: +Y (Up), 3: -Y (Down)
DIRS = {
    0: (1.0, 0.0),  # East
    1: (-1.0, 0.0), # West
    2: (0.0, 1.0),  # North
    3: (0.0, -1.0)  # South
}

# Clockwise turn logic (e.g., 0(+X) -> 3(-Y))
