    0: 3, # +X -> -Y
    1: 2, # -X -> +Y
    2: 0, # +Y -> +X
    3: 1  # -Y -> -X
}

class Ant:
    def __init__(self, ant_id, x, y, direction_id):
        self.id = ant_id
        self.x = x
        self.y = y
        self.direction_id = direction_id
        self.active = True
        self.t_start = 0.0
        self.path_history = [(x, y, 0.0)]

    @property
    def dx(self):
        return DIRS[self.direction_id][0]

    @property
    def dy(self):
        return DIRS[self.direction_id][1]

    def move(self, dt):
        if not self.active:
            return
        self.x += self.dx * dt
        self.y += self.dy * dt
        self.t_start += dt
        self.path_history.append((self.x, self.y, self.t_start))

    def calculate_boundary_time(self):
        time_x = None
        if self.dx > 1e-9: # Moving Right
            time_x = (BOARD_SIZE - self.x) / self.dx
        elif self.dx < -1e-9: # Moving Left
            time_x = (0.0 - self.x) / self.dx

        time_y = None
        if self.dy > 1e-9: # Moving Up
            time_y = (BOARD_SIZE - self.y) / self.dy
        elif self.dy < -1e-9: # Moving Down
            time_y = (0.0 - self.y) / self.dy

        times = []
        if time_x is not None and time_x > 1e-9:
            times.append(time_x)
        if time_y is not None and time_y > 1e-9:
            times.append(time_y)

        if not times:
            return float('inf')

        return min(times)

